function S.actor_scale(actor)
  return S.ACTOR_SCALE[actor] or S.SCALE_DEFAULT
end
S.runs = {}

local function rows_of(str)
  local rows = {}
  for line in string.gmatch(str, "[^\n]+") do
    rows[#rows + 1] = line
  end
  return rows
end

local function runs_of(rows)
  local runs = {}
  for y = 1, #rows do
    local row = rows[y]
    local x = 1
    while x <= #row do
      local c = string.sub(row, x, x)
      local x2 = x
      while x2 < #row and string.sub(row, x2 + 1, x2 + 1) == c do
        x2 = x2 + 1
      end
      if c ~= "." then
        runs[#runs + 1] = { x - 1, y - 1, x2 - x + 1, c }
      end
      x = x2 + 1
    end
  end
  return runs
end

function S.init_sprites()


  S.layer_runs = {}
  for slot, items in pairs(S.layer_art or {}) do
    S.layer_runs[slot] = {}
    for id, item in pairs(items) do
      local grid = rows_of(item.grid)
      S.layer_runs[slot][id] = {
        runs = runs_of(grid), w = #grid[1], h = #grid, dx = item.dx, dy = item.dy,



        density = item.density or 1,
      }
    end
  end
  for id, spr in pairs(S.sprites) do
    local base = runs_of(rows_of(spr.base))




    local bottom, left, right, top = 0, 32, 0, 32
    for i = 1, #base do
      local r = base[i]
      if r[2] + 1 > bottom then bottom = r[2] + 1 end
      if r[2] < top then top = r[2] end
      if r[1] < left then left = r[1] end
      if r[1] + r[3] > right then right = r[1] + r[3] end
    end
    local entry = {
      base = base, bottom = bottom, left = left, top = top, width = right - left,
      face = spr.face, expr = {}, expr_div = {},
    }
    for name, str in pairs(spr.expr) do
      local grid = rows_of(str)
      entry.expr[name] = runs_of(grid)



      entry.expr_div[name] = (#grid == spr.face.h * 2) and 2 or 1
    end
    S.runs[id] = entry
  end
end

local function draw_runs(runs, ox, oy, sc)
  for i = 1, #runs do
    local r = runs[i]
    local col = S.palette[r[4]]
    screen.fill_rect(ox + r[1] * sc, oy + r[2] * sc, r[3] * sc, sc, col[1], col[2], col[3])
  end
end

function S.has_expr(actor, expression)
  local a = S.runs[actor]
  return a ~= nil and a.expr[expression .. "_closed"] ~= nil
end

function S.wrap(text, max)
  local lines, cur = {}, ""
  for word in string.gmatch(text, "%S+") do
    if #cur == 0 then
      cur = word
    elseif #cur + 1 + #word <= max then
      cur = cur .. " " .. word
    else
      lines[#lines + 1] = cur
      cur = word
    end
  end
  if #cur > 0 then lines[#lines + 1] = cur end
  return lines
end








function S.draw_art_error()
  screen.clear(26, 28, 44)
  local y = 24
  local function emit(line)
    if y > 208 then return false end
    screen.text(4, y, line, 2, 239, 125, 87)
    y = y + 18
    return true
  end
  for raw in string.gmatch(S.art_error, "[^\n]+") do
    for _, wrapped in ipairs(S.wrap(raw, 11)) do



      local line = wrapped
      while #line > 11 do
        if not emit(string.sub(line, 1, 11)) then
          screen.flip()
          return
        end
        line = string.sub(line, 12)
      end
      if not emit(line) then
        screen.flip()
        return
      end
    end
  end
  screen.flip()
end




function S.draw_character(actor, expression, mouth_open, x, y, layers)
  local a = S.runs[actor]
  if not a then return end
  local sc = S.actor_scale(actor)







  local bp = layers and layers.back_prop
  local bpi = bp and S.layer_runs.back_prop and S.layer_runs.back_prop[bp]
  if bpi then
    local d = bpi.density
    local px = sc // d
    local ox = x + a.left * sc + ((a.width * d - bpi.w) // 2) * px + bpi.dx * px
    local oy = y + a.top * sc - bpi.h * px + bpi.dy * px
    draw_runs(bpi.runs, ox, oy, px)
  end
  draw_runs(a.base, x, y, sc)
  local key = expression .. (mouth_open and "_open" or "_closed")
  if not a.expr[key] then key = expression .. "_closed" end
  local e = a.expr[key]
  if e then

    draw_runs(e, x + a.face.x * sc, y + a.face.y * sc, sc // a.expr_div[key])
  end



  local hw = layers and layers.headwear
  local item = hw and S.layer_runs.headwear and S.layer_runs.headwear[hw]
  if item then
    local d = item.density
    local px = sc // d
    local ox = x + a.face.x * sc + ((a.face.w * d - item.w) // 2) * px + item.dx * px
    local oy = y + a.face.y * sc - item.h * px + item.dy * px
    draw_runs(item.runs, ox, oy, px)
  end






  local fp = layers and layers.front_prop
  local fpi = fp and S.layer_runs.front_prop and S.layer_runs.front_prop[fp]
  local hand = S.hand and S.hand[actor]
  if fpi and hand then
    local d = fpi.density
    local px = sc // d
    local ox = x + hand.x * sc + ((d - fpi.w) // 2) * px + fpi.dx * px
    local oy = y + (hand.y + 1) * sc - fpi.h * px + fpi.dy * px
    draw_runs(fpi.runs, ox, oy, px)
  end
end


function S.draw_grounded(actor, expression, mouth_open, x, baseline_y, layers)
  local a = S.runs[actor]
  if not a then return end
  S.draw_character(actor, expression, mouth_open, x, baseline_y - a.bottom * S.actor_scale(actor), layers)
end




function S.place_character(actor, expression, mouth_open, layers)
  local a = S.runs[actor]
  if not a then return end
  local sc = S.actor_scale(actor)
  local x = math.floor((S.SCREEN_W - a.width * sc) / 2) - a.left * sc
  if actor == "miss_moon" then
    S.draw_character(actor, expression, mouth_open, x, S.MOON_Y, layers)
  else
    S.draw_grounded(actor, expression, mouth_open, x, S.BASELINE_Y, layers)
  end
end









local function clip_path(id)
  return S.performance.audio_root .. "/" .. id .. ".wav"
end



local PRELOAD_PER_TICK = 4
local next_clip = 1

function S.preload_clips()
  next_clip = 1
end




function S.sfx_trigger(id)
  local path = clip_path(id)
  audio.preload(path)
  audio.play(path, 1)
end

function S.sfx_update(dt_ms)
  local clips = S.performance.clips
  for _ = 1, PRELOAD_PER_TICK do
    if next_clip > #clips then return end
    audio.preload(clip_path(clips[next_clip]))
    next_clip = next_clip + 1
  end
end

function S.line_start(beat)
  audio.stop(0)
  if beat.line then
    audio.play(clip_path(beat.line), 0)
  end
end

function S.sound_stop()
  audio.stop()
end

function S.line_resume(beat, offset_ms)



  if beat.line then
    audio.play(clip_path(beat.line), 0, offset_ms)
  end
end













local TITLE_MS = 2000




local MAX_DT_MS = 1000
local NOMINAL_DT_MS = 100

S.p = { state = "title", beat_i = 1, elapsed = 0, sfx_next = 1 }

function S.player_reset()
  S.p.state = "title"
  S.p.beat_i = 1
  S.p.elapsed = 0
  S.p.sfx_next = 1
  S.sound_stop()
  S.sfx_trigger("sfx_chime")
end




function S.player_hold()
  S.p.state = "ready"
  S.p.beat_i = 1
  S.p.elapsed = 0
  S.p.sfx_next = 1
  S.sound_stop()
end





function S.player_update(dt_ms)
  local p = S.p
  if p.state == "paused" or p.state == "done" or p.state == "ready" then return end
  if dt_ms > MAX_DT_MS then dt_ms = NOMINAL_DT_MS end
  p.elapsed = p.elapsed + dt_ms

  if p.state == "title" then
    if p.elapsed < TITLE_MS then
      S.sfx_update(dt_ms)
      return
    end


    p.state = "playing"
    p.elapsed = p.elapsed - TITLE_MS
    p.beat_i = 1
    p.sfx_next = 1
    S.line_start(S.performance.beats[1])
  end

  local beats = S.performance.beats
  local beat = beats[p.beat_i]
  while p.elapsed >= beat.duration do
    p.elapsed = p.elapsed - beat.duration
    if p.beat_i >= #beats then
      p.state = "done"
      break
    end
    p.beat_i = p.beat_i + 1
    p.sfx_next = 1
    beat = beats[p.beat_i]
    S.line_start(beat)
  end

  if p.state == "playing" then
    while beat.sfx[p.sfx_next] and p.elapsed >= beat.sfx[p.sfx_next].at do
      S.sfx_trigger(beat.sfx[p.sfx_next].id)
      p.sfx_next = p.sfx_next + 1
    end
  end

  S.sfx_update(dt_ms)
end

function S.player_button(index)


  if S.p.state == "ready" then
    S.player_reset()
    return
  end
  if index == 0 then
    S.player_reset()
  elseif index == 1 then
    if S.p.state == "playing" then
      S.p.state = "paused"
      S.sound_stop()
    elseif S.p.state == "paused" then
      S.p.state = "playing"
      S.line_resume(S.performance.beats[S.p.beat_i], S.p.elapsed)
    end
  end
end



function S.mouth_open()
  local p = S.p
  if p.state ~= "playing" then return false end
  local beat = S.performance.beats[p.beat_i]
  if beat.animation ~= "speak" or not beat.line_ms then return false end
  if p.elapsed >= beat.line_ms then return false end
  return (math.floor(p.elapsed / 200) % 2) == 1
end







local BG = { 26, 28, 44 }





local function draw_title()
  screen.clear(BG[1], BG[2], BG[3])
  local lines = S.wrap(S.performance.title, 11)
  local y = 60
  for i = 1, #lines do
    screen.text(67 - #lines[i] * 6, y, lines[i], 2, 255, 205, 117)
    y = y + 20
  end
  if S.p.state == "ready" then
    screen.text(28, 200, "Press to play", 1, 148, 176, 194)
  end
  screen.flip()
end

local function draw_beat()
  local beat = S.performance.beats[S.p.beat_i]
  local member = S.performance.cast[beat.character]
  screen.clear(BG[1], BG[2], BG[3])


  if member then
    local expr = beat.expression
    if not S.has_expr(member.actor, expr) then expr = member.default_expression end



    S.place_character(member.actor, expr, S.mouth_open(), beat.layers or member.layers)
    screen.text(2, 2, member.name, 1, 148, 176, 194)
  end
  if S.p.state == "paused" then
    screen.text(97, 2, "PAUSED", 1, 239, 125, 87)
  end
  screen.flip()
end

local function draw_done()
  screen.clear(BG[1], BG[2], BG[3])
  S.place_character("miss_moon", "happy", false)
  screen.text(25, 150, "The End", 2, 255, 205, 117)
  screen.text(7, 224, "Button 0: play again", 1, 148, 176, 194)
  screen.flip()
end

function init(ctx)
  if S.art_error then
    S.draw_art_error()
    return
  end
  S.init_sprites()
  screen.clear(BG[1], BG[2], BG[3])
  screen.text(19, 116, "Loading story...", 1, 148, 176, 194)
  screen.flip()
  S.preload_clips()
  S.player_reset()
  draw_title()
end




local drawn_state = nil

function on_tick(ctx, dt_ms)
  if S.art_error then return end
  S.player_update(dt_ms)
  local state = S.p.state
  if state == "ready" then
    if drawn_state ~= "ready" then draw_title() end
  elseif state == "title" then
    draw_title()
  elseif state == "done" then
    draw_done()
  else
    draw_beat()
  end
  drawn_state = state
end

function on_event(ctx, e)
  if S.art_error then return end
  if e.name == "button" then
    S.player_button(e.data.index)
  elseif e.name == "boot_restore" then
    S.player_hold()
  end
end
